pub fn handle_blobs_by_range_request(
    self: Arc<Self>,
    peer_id: PeerId,
    inbound_request_id: InboundRequestId,
    req: BlobsByRangeRequest,
) {
    let client = self.network_globals.client(&peer_id);
    Span::current().record("client", field::display(client.kind));

    self.terminate_response_stream(
        peer_id,
        inbound_request_id,
        self.handle_blobs_by_range_request_inner(peer_id, inbound_request_id, req),
        Response::BlobsByRange,
    );
}

/// Handle a `BlobsByRange` request from the peer.
fn handle_blobs_by_range_request_inner(
    &self,
    peer_id: PeerId,
    inbound_request_id: InboundRequestId,
    req: BlobsByRangeRequest,
) -> Result<(), (RpcErrorResponse, &'static str)> {
    debug!(
        ?peer_id,
        count = req.count,
        start_slot = req.start_slot,
        "Received BlobsByRange Request"
    );

    let request_start_slot = Slot::from(req.start_slot);

    let data_availability_boundary_slot = match self.chain.data_availability_boundary() {
        Some(boundary) => boundary.start_slot(T::EthSpec::slots_per_epoch()),
        None => {
            debug!("Deneb fork is disabled");
            return Err((RpcErrorResponse::InvalidRequest, "Deneb fork is disabled"));
        }
    };

    let oldest_blob_slot = self
        .chain
        .store
        .get_blob_info()
        .oldest_blob_slot
        .unwrap_or(data_availability_boundary_slot);
    if request_start_slot < oldest_blob_slot {
        debug!(
            %request_start_slot,
            %oldest_blob_slot,
            %data_availability_boundary_slot,
            "Range request start slot is older than data availability boundary."
        );

        return if data_availability_boundary_slot < oldest_blob_slot {
            Err((
                RpcErrorResponse::ResourceUnavailable,
                "blobs pruned within boundary",
            ))
        } else {
            Err((
                RpcErrorResponse::InvalidRequest,
                "Req outside availability period",
            ))
        };
    }

    let block_roots =
        self.get_block_roots_for_slot_range(req.start_slot, req.count, "BlobsByRange")?;

    let current_slot = self
        .chain
        .slot()
        .unwrap_or_else(|_| self.chain.slot_clock.genesis_slot());

    let log_results = |peer_id, req: BlobsByRangeRequest, blobs_sent| {
        debug!(
            %peer_id,
            start_slot = req.start_slot,
            %current_slot,
            requested = req.count,
            returned = blobs_sent,
            "BlobsByRange outgoing response processed"
        );
    };

    let mut blobs_sent = 0;

    for root in block_roots {
        match self.chain.get_blobs(&root) {
            Ok(blob_sidecar_list) => {
                for blob_sidecar in blob_sidecar_list.iter() {
                    // Due to skip slots, blobs could be out of the range, we ensure they
                    // are in the range before sending
                    if blob_sidecar.slot() >= request_start_slot
                        && blob_sidecar.slot() < request_start_slot + req.count
                    {
                        blobs_sent += 1;
                        self.send_network_message(NetworkMessage::SendResponse {
                            peer_id,
                            inbound_request_id,
                            response: Response::BlobsByRange(Some(blob_sidecar.clone())),
                        });
                    }
                }
            }
            Err(e) => {
                error!(
                    request = ?req,
                    %peer_id,
                    block_root = ?root,
                    error = ?e,
                    "Error fetching blobs block root"
                );
                log_results(peer_id, req, blobs_sent);

                return Err((
                    RpcErrorResponse::ServerError,
                    "No blobs and failed fetching corresponding block",
                ));
            }
        }
    }
    log_results(peer_id, req, blobs_sent);

    Ok(())
}

/// Handle a `DataColumnsByRange` request from the peer.
#[instrument(
    name = SPAN_HANDLE_DATA_COLUMNS_BY_RANGE_REQUEST,
    parent = None,
    skip_all,
    level = "debug",
    fields(peer_id = %peer_id, non_custody_indices = tracing::field::Empty, client = tracing::field::Empty)
)]
pub fn handle_data_columns_by_range_request(
    &self,
    peer_id: PeerId,
    inbound_request_id: InboundRequestId,
    req: DataColumnsByRangeRequest,
) {
    let epoch = Slot::new(req.start_slot).epoch(T::EthSpec::slots_per_epoch());
    self.record_data_column_request_in_span(
        &peer_id,
        &req.columns,
        Some(epoch),
        Span::current(),
    );

/// Returns the min epoch for blob / data column sidecar requests based on the current epoch.
/// Switch to use the column sidecar config once the `blob_retention_epoch` has passed Fulu fork epoch.
pub fn min_epoch_data_availability_boundary(&self, current_epoch: Epoch) -> Option<Epoch> {
    let fork_epoch = self.deneb_fork_epoch?;
    let blob_retention_epoch =
        current_epoch.saturating_sub(self.min_epochs_for_blob_sidecars_requests);
    match self.fulu_fork_epoch {
        Some(fulu_fork_epoch) if blob_retention_epoch > fulu_fork_epoch => Some(
            current_epoch.saturating_sub(self.min_epochs_for_data_column_sidecars_requests),
        ),
        _ => Some(std::cmp::max(fork_epoch, blob_retention_epoch)),
    }
}

pub fn all_data_column_sidecar_subnets(&self) -> impl Iterator<Item = DataColumnSubnetId> {
    (0..self.data_column_sidecar_subnet_count).map(DataColumnSubnetId::new)
}

/// Worst-case compressed length for a given payload of size n when using snappy.
///
/// https://github.com/google/snappy/blob/32ded457c0b1fe78ceb8397632c416568d6714a0/snappy.cc#L218C1-L218C47
/// https://github.com/ethereum/consensus-specs/blob/dev/specs/phase0/p2p-interface.md#max_compressed_len
fn max_compressed_len_snappy(n: usize) -> Option<usize> {
    32_usize.checked_add(n)?.checked_add(n / 6)
}

/// Max compressed length of a message that we receive over gossip.
pub fn max_compressed_len(&self) -> usize {
    Self::max_compressed_len_snappy(self.max_payload_size as usize)
        .expect("should not overflow")
}

/// Max allowed size of a raw, compressed message received over the network.
///
/// https://github.com/ethereum/consensus-specs/blob/dev/specs/phase0/p2p-interface.md#max_compressed_len
pub fn max_message_size(&self) -> usize {
    std::cmp::max(
        // 1024 to account for framing + encoding overhead
        Self::max_compressed_len_snappy(self.max_payload_size as usize)
            .expect("should not overflow")
            .safe_add(1024)
            .expect("should not overflow"),
        //1MB
        1024 * 1024,
    )
}

